def parse(text):
    """Parse 'key = value' lines into a dict.

    Blank lines and lines starting with '#' are ignored. After a value, whitespace followed by '#' starts a comment.
    """
    result = {}
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        key, value = line.split("=", 1)
        value = value.strip()
        value = value.split(" #", 1)[0].strip()
        result[key.strip()] = value
    return result

diff.stats.py:
def mean(values):
    """Arithmetic mean. An empty list raises ValueError."""
    if not values:
        raise ValueError("mean of an empty list")
    return sum(values) / len(values)


def median(values):
    """Middle value; for an even count, the mean of the two middle values. An empty list raises ValueError."""
    if not values:
        raise ValueError("median of an empty list")
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

